package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {





    @Test
    public void testCreateNumber_HexInteger() {
        // Test 0x prefix
        assertEquals(Integer.class, NumberUtils.createNumber("0x7FFFFFFF").getClass());
        // Test 0X prefix
        assertEquals(Integer.class, NumberUtils.createNumber("0X123").getClass());
        // Test -0x prefix
        assertEquals(Integer.class, NumberUtils.createNumber("-0x1").getClass());
        // Test -0X prefix
        assertEquals(Integer.class, NumberUtils.createNumber("-0X1").getClass());
        // Test # prefix
        assertEquals(Integer.class, NumberUtils.createNumber("#123").getClass());
        // Test -# prefix
        assertEquals(Integer.class, NumberUtils.createNumber("-#123").getClass());
        // Test leading zeros in hex
        assertEquals(Integer.class, NumberUtils.createNumber("0x00000001").getClass());
    }
































}

