package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {























    @Test
    public void testCreateNumber_WithSuffix_L() {
        assertEquals(Long.class, NumberUtils.createNumber("123L").getClass());
        assertEquals(Long.class, NumberUtils.createNumber("-123l").getClass());
        // Very large L should be BigInteger
        assertEquals(BigInteger.class, NumberUtils.createNumber("12345678901234567890L").getClass());

        // Invalid L
        try {
            NumberUtils.createNumber("1.23L");
            fail("Should throw NumberFormatException");
        } catch (NumberFormatException e) {}
    }














}

package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
