import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {

























    @Test
    public void testCreateNumber_WithSuffix_F() {
        assertEquals(Float.class, NumberUtils.createNumber("123.456F").getClass());
        assertEquals(Float.class, NumberUtils.createNumber("123.456f").getClass());

        // Test fallback to Double if Float fails/is infinite
        // Note: we rely on the logic that if f.isInfinite() it falls through
        // Large number that exceeds float range but fits in double
        assertEquals(Double.class, NumberUtils.createNumber("1e40F").getClass());
    }












}

